//! Cross-language agreement: the Rust implementation must reproduce every byte of the shared
//! vectors in `spec/test-vectors/` (generated by the TypeScript implementation).

use serde_json::Value;
use stele_canonical::{
    normalize_inline, normalize_text, parse_canonical, Attachment, Block, CanonError, Content,
};
use stele_core::acceptance::{acceptance_id, accumulate};
use stele_core::message::{acceptance_message, AcceptanceMessageFields};
use stele_core::passkey::{
    check_authenticator_data, check_client_data, enrollment_statement, passkey_acceptance_id,
    passkey_acceptance_message, rotation_statement, webauthn_challenge, PasskeyAcceptanceFields,
    PASSKEY_ACCEPTANCE_TAG, PASSKEY_ENROLL_TAG, PASSKEY_ROTATE_TAG,
};
use stele_core::proof::{proof_id, proof_message, ProofMessageFields};
use stele_core::time::format_rfc3339;
use stele_core::validate::*;
use stele_core::version::{version_hash, version_json, VersionFields};
use stele_core::CoreError;

#[test]
fn merkle_batch_vectors() {
    use stele_core::batch::{batch_id, leaf_hash, merkle_proof, merkle_root, verify_proof};
    let v = load("batch.json");
    for t in v["trees"].as_array().unwrap() {
        let n = t["leafCount"].as_u64().unwrap() as u32;
        let leaves: Vec<[u8; 32]> = t["leaves"]
            .as_array()
            .unwrap()
            .iter()
            .map(|l| {
                let leaf = leaf_hash(
                    l["protocol"].as_u64().unwrap() as u8,
                    &hex32(&l["acceptanceId"]),
                );
                assert_eq!(leaf, hex32(&l["leaf"]));
                leaf
            })
            .collect();
        let root = merkle_root(&leaves).unwrap();
        assert_eq!(root, hex32(&t["root"]), "root of {n}");
        for (i, p) in t["proofs"].as_array().unwrap().iter().enumerate() {
            let proof: Vec<[u8; 32]> = p.as_array().unwrap().iter().map(hex32).collect();
            assert_eq!(merkle_proof(&leaves, i).unwrap(), proof, "proof {i} of {n}");
            assert!(verify_proof(&leaves[i], i as u32, n, &proof, &root));
        }
    }
    for b in v["batchIds"].as_array().unwrap() {
        let id = batch_id(
            &b58_32(&b["organization"]),
            &b58_32(&b["nonceShard"]),
            &hex32(&b["root"]),
            b["leafCount"].as_u64().unwrap() as u32,
            b["sequence"].as_str().unwrap().parse().unwrap(),
        );
        assert_eq!(id, hex32(&b["batchId"]));
    }
}

fn load(name: &str) -> Value {
    let path = format!(
        "{}/../../spec/test-vectors/{name}",
        env!("CARGO_MANIFEST_DIR")
    );
    let text = std::fs::read_to_string(&path).unwrap_or_else(|e| panic!("read {path}: {e}"));
    serde_json::from_str(&text).expect("valid JSON")
}

fn hex32(v: &Value) -> [u8; 32] {
    let mut out = [0u8; 32];
    hex::decode_to_slice(v.as_str().expect("hex string"), &mut out).expect("32-byte hex");
    out
}

fn b58_32(v: &Value) -> [u8; 32] {
    let bytes = bs58::decode(v.as_str().expect("base58 string"))
        .into_vec()
        .expect("base58");
    bytes.try_into().expect("32 bytes")
}

fn error_class(e: &CanonError) -> &'static str {
    match e {
        CanonError::ForbiddenCharacter(_) => "FORBIDDEN_CHARACTER",
        CanonError::EmptyText => "EMPTY_TEXT",
        _ => "OTHER",
    }
}

fn check_outcome(case: &str, kind: &str, actual: Result<String, CanonError>, expected: &Value) {
    match (actual, expected.get("ok"), expected.get("error")) {
        (Ok(s), Some(ok), _) => assert_eq!(s, ok.as_str().unwrap(), "{case} ({kind})"),
        (Err(e), _, Some(err)) => {
            assert_eq!(error_class(&e), err.as_str().unwrap(), "{case} ({kind})")
        }
        (got, _, _) => {
            panic!("{case} ({kind}): outcome mismatch, got {got:?}, expected {expected}")
        }
    }
}

#[test]
fn text_normalization_vectors() {
    let v = load("text-normalization.json");
    let cases = v["cases"].as_array().unwrap();
    assert!(cases.len() >= 20);
    for c in cases {
        let name = c["name"].as_str().unwrap();
        let input = c["input"].as_str().unwrap();
        check_outcome(name, "text", normalize_text(input), &c["text"]);
        check_outcome(name, "inline", normalize_inline(input), &c["inline"]);
    }
}

fn block_from_json(b: &Value) -> Block {
    match b["type"].as_str().unwrap() {
        "heading" => Block::Heading {
            level: b["level"].as_u64().unwrap() as u8,
            text: b["text"].as_str().unwrap().into(),
        },
        "paragraph" => Block::Paragraph {
            text: b["text"].as_str().unwrap().into(),
        },
        "list" => Block::List {
            ordered: b["ordered"].as_bool().unwrap_or(false),
            items: b["items"]
                .as_array()
                .unwrap()
                .iter()
                .map(|i| i.as_str().unwrap().to_string())
                .collect(),
        },
        other => panic!("unknown block type {other}"),
    }
}

#[test]
fn content_vectors() {
    let v = load("content.json");
    for c in v["cases"].as_array().unwrap() {
        let name = c["name"].as_str().unwrap();
        let input = &c["input"];
        let raw = Content {
            attachments: input
                .get("attachments")
                .and_then(Value::as_array)
                .map(|a| {
                    a.iter()
                        .map(|x| Attachment {
                            media_type: x["mediaType"].as_str().unwrap().into(),
                            name: x["name"].as_str().unwrap().into(),
                            sha256: x["sha256"].as_str().unwrap().into(),
                            size: x["size"].as_u64().unwrap(),
                        })
                        .collect()
                })
                .unwrap_or_default(),
            blocks: input["blocks"]
                .as_array()
                .unwrap()
                .iter()
                .map(block_from_json)
                .collect(),
            change_summary: input
                .get("changeSummary")
                .and_then(Value::as_str)
                .map(str::to_string),
        };
        let canonical = raw.canonicalize().unwrap_or_else(|e| panic!("{name}: {e}"));
        let bytes = canonical.to_canonical_bytes();
        assert_eq!(
            String::from_utf8(bytes.clone()).unwrap(),
            c["canonical"].as_str().unwrap(),
            "{name}: canonical bytes"
        );
        assert_eq!(
            hex::encode(stele_canonical::content_hash(&bytes)),
            c["contentHash"].as_str().unwrap(),
            "{name}: hash"
        );
        assert_eq!(
            parse_canonical(&bytes).unwrap(),
            canonical,
            "{name}: parse round trip"
        );
    }
    for c in v["invalidCanonical"].as_array().unwrap() {
        let name = c["name"].as_str().unwrap();
        assert!(
            parse_canonical(c["bytes"].as_str().unwrap().as_bytes()).is_err(),
            "{name} must be rejected"
        );
    }
}

#[test]
fn version_vectors() {
    let v = load("version.json");
    for c in v["cases"].as_array().unwrap() {
        let name = c["name"].as_str().unwrap();
        let f = &c["fields"];
        let program = b58_32(&f["program"]);
        let org = b58_32(&f["organization"]);
        let doc = b58_32(&f["document"]);
        let content = hex32(&f["contentHash"]);
        let prev = if f["previousVersionHash"].is_null() {
            None
        } else {
            Some(hex32(&f["previousVersionHash"]))
        };
        let fields = VersionFields {
            chain_id: f["chainId"].as_str().unwrap(),
            program: &program,
            organization: &org,
            document: &doc,
            document_type: f["documentType"].as_str().unwrap(),
            locale: f["locale"].as_str().unwrap(),
            version: f["version"].as_u64().unwrap() as u32,
            previous_version_hash: prev.as_ref(),
            title: f["title"].as_str().unwrap(),
            version_label: f["versionLabel"].as_str().unwrap(),
            effective_at: f["effectiveAt"].as_i64().unwrap(),
            content_hash: &content,
        };
        assert_eq!(
            version_json(&fields),
            c["json"].as_str().unwrap(),
            "{name}: json"
        );
        assert_eq!(
            hex::encode(version_hash(&fields)),
            c["versionHash"].as_str().unwrap(),
            "{name}: hash"
        );
    }
}

#[test]
fn rfc3339_vectors() {
    let v = load("rfc3339.json");
    for c in v["cases"].as_array().unwrap() {
        assert_eq!(
            format_rfc3339(c["timestamp"].as_i64().unwrap()).unwrap(),
            c["formatted"].as_str().unwrap()
        );
    }
    for t in v["invalid"].as_array().unwrap() {
        assert!(format_rfc3339(t.as_i64().unwrap()).is_err());
    }
    // Independent anchors (not generated).
    assert_eq!(format_rfc3339(951_782_400).unwrap(), "2000-02-29T00:00:00Z");
}

#[test]
fn acceptance_message_vectors() {
    let v = load("acceptance-message.json");
    for c in v["cases"].as_array().unwrap() {
        let name = c["name"].as_str().unwrap();
        let f = &c["fields"];
        let version_hash = hex32(&f["versionHash"]);
        let signer = b58_32(&f["signer"]);
        let mut tag = [0u8; 8];
        hex::decode_to_slice(f["nonceTag"].as_str().unwrap(), &mut tag).unwrap();
        let fields = AcceptanceMessageFields {
            org_name: f["orgName"].as_str().unwrap(),
            org_verified_domain: f["orgVerifiedDomain"].as_str(),
            title: f["title"].as_str().unwrap(),
            version_label: f["versionLabel"].as_str().unwrap(),
            version: f["version"].as_u64().unwrap() as u32,
            version_hash: &version_hash,
            signer: &signer,
            network_label: f["networkLabel"].as_str().unwrap(),
            issued_at: f["issuedAt"].as_i64().unwrap(),
            expires_at: f["expiresAt"].as_i64().unwrap(),
            shard_id: f["shardId"].as_u64().unwrap() as u16,
            nonce_index: f["nonceIndex"].as_u64().unwrap() as u32,
            nonce_tag: &tag,
        };
        let message = acceptance_message(&fields, c["requestDomain"].as_str().unwrap()).unwrap();
        assert_eq!(message, c["message"].as_str().unwrap(), "{name}: message");
        assert_eq!(
            hex::encode(stele_core::hash::sha256(message.as_bytes())),
            c["messageHash"].as_str().unwrap(),
            "{name}: hash"
        );
    }
}

#[test]
fn acceptance_id_vectors() {
    let v = load("acceptance-id.json");
    let version = hex32(&v["version"]);
    let signer = hex32(&v["signer"]);
    let mut acc = [0u8; 32];
    for step in v["chain"].as_array().unwrap() {
        let msg_hash = hex32(&step["messageHash"]);
        let mut sig = [0u8; 64];
        hex::decode_to_slice(step["signature"].as_str().unwrap(), &mut sig).unwrap();
        let id = acceptance_id(&version, &signer, &msg_hash, &sig);
        assert_eq!(hex::encode(id), step["acceptanceId"].as_str().unwrap());
        acc = accumulate(&acc, &id);
        assert_eq!(hex::encode(acc), step["accumulatorAfter"].as_str().unwrap());
    }
}

#[test]
fn validation_vectors() {
    let v = load("validation.json");
    type Validator = fn(&str) -> Result<(), stele_core::CoreError>;
    let validators: Vec<(&str, Validator)> = vec![
        ("orgName", validate_org_name),
        ("title", validate_title),
        ("slug", validate_slug),
        ("documentType", validate_document_type),
        ("locale", validate_locale),
        ("versionLabel", validate_version_label),
        ("storageUri", validate_storage_uri),
        ("verifiedDomain", validate_verified_domain),
        ("requestDomain", validate_request_domain),
        ("chainId", validate_chain_id),
        ("networkLabel", validate_network_label),
    ];
    for (field, f) in validators {
        for case in v["fields"][field]
            .as_array()
            .unwrap_or_else(|| panic!("missing {field}"))
        {
            let value = case["value"].as_str().unwrap();
            assert_eq!(
                f(value).is_ok(),
                case["valid"].as_bool().unwrap(),
                "{field}: {value:?}"
            );
        }
    }
}

#[test]
fn proof_message_vectors() {
    let v = load("proof-message.json");
    let cases = v["cases"].as_array().unwrap();
    assert!(cases.len() >= 2);
    for c in cases {
        let name = c["name"].as_str().unwrap();
        let f = &c["fields"];
        let organization = b58_32(&f["organization"]);
        let statement_hash = hex32(&f["statementHash"]);
        let signer = b58_32(&f["signer"]);
        let mut tag = [0u8; 8];
        hex::decode_to_slice(f["nonceTag"].as_str().unwrap(), &mut tag).unwrap();
        let fields = ProofMessageFields {
            proof_type: f["proofType"].as_u64().unwrap() as u8,
            org_name: f["orgName"].as_str().unwrap(),
            org_verified_domain: f["orgVerifiedDomain"].as_str(),
            organization: &organization,
            statement_hash: &statement_hash,
            signer: &signer,
            network_label: f["networkLabel"].as_str().unwrap(),
            chain_id: f["chainId"].as_str().unwrap(),
            issued_at: f["issuedAt"].as_i64().unwrap(),
            expires_at: f["expiresAt"].as_i64().unwrap(),
            shard_id: f["shardId"].as_u64().unwrap() as u16,
            nonce_index: f["nonceIndex"].as_u64().unwrap() as u32,
            nonce_tag: &tag,
        };
        let message = proof_message(&fields, c["requestDomain"].as_str().unwrap()).unwrap();
        assert_eq!(message, c["message"].as_str().unwrap(), "{name}: message");
        let message_hash = stele_core::hash::sha256(message.as_bytes());
        assert_eq!(
            hex::encode(message_hash),
            c["messageHash"].as_str().unwrap()
        );
        let mut signature = [0u8; 64];
        hex::decode_to_slice(c["signature"].as_str().unwrap(), &mut signature).unwrap();
        let id = proof_id(
            &organization,
            &signer,
            &statement_hash,
            &message_hash,
            &signature,
        );
        assert_eq!(
            hex::encode(id),
            c["proofId"].as_str().unwrap(),
            "{name}: proof id"
        );
    }
}

#[test]
fn statement_hash_vector() {
    // The statement's canonical bytes are produced off-chain only; the hash is what the program
    // records and the customer signs.
    let v = load("statement.json");
    let canonical = v["canonical"].as_str().unwrap();
    assert_eq!(
        hex::encode(stele_core::hash::sha256(canonical.as_bytes())),
        v["statementHash"].as_str().unwrap()
    );
}

fn hex_n<const N: usize>(v: &Value) -> [u8; N] {
    let mut out = [0u8; N];
    hex::decode_to_slice(v.as_str().expect("hex string"), &mut out).expect("hex of the right size");
    out
}

fn passkey_error(e: CoreError) -> &'static str {
    match e {
        CoreError::InvalidClientData => "INVALID_CLIENT_DATA",
        CoreError::OriginMismatch => "ORIGIN_MISMATCH",
        CoreError::CrossOriginCeremony => "CROSS_ORIGIN_CEREMONY",
        CoreError::InvalidAuthenticatorData => "INVALID_AUTHENTICATOR_DATA",
        CoreError::RelyingPartyMismatch => "RELYING_PARTY_MISMATCH",
        CoreError::UserNotVerified => "USER_NOT_VERIFIED",
        CoreError::ClientDataHashMismatch => "CLIENT_DATA_HASH_MISMATCH",
        other => panic!("unexpected error {other:?}"),
    }
}

#[test]
fn passkey_p256_vectors() {
    let v = load("passkey-p256.json");
    let signer: [u8; 33] = hex_n(&v["signerPublicKey"]);
    let rp_id = v["rpId"].as_str().unwrap();

    for c in v["acceptances"].as_array().unwrap() {
        let name = c["name"].as_str().unwrap();
        let f = &c["fields"];
        let version_hash = hex32(&f["versionHash"]);
        let tag: [u8; 8] = hex_n(&f["nonceTag"]);
        let fields = PasskeyAcceptanceFields {
            org_name: f["orgName"].as_str().unwrap(),
            org_verified_domain: f["orgVerifiedDomain"].as_str(),
            title: f["title"].as_str().unwrap(),
            version_label: f["versionLabel"].as_str().unwrap(),
            version: f["version"].as_u64().unwrap() as u32,
            version_hash: &version_hash,
            signer: &signer,
            network_label: f["networkLabel"].as_str().unwrap(),
            issued_at: f["issuedAt"].as_i64().unwrap(),
            expires_at: f["expiresAt"].as_i64().unwrap(),
            shard_id: f["shardId"].as_u64().unwrap() as u16,
            nonce_index: f["nonceIndex"].as_u64().unwrap() as u32,
            nonce_tag: &tag,
        };
        let request_domain = c["requestDomain"].as_str().unwrap();
        let message = passkey_acceptance_message(&fields, request_domain).unwrap();
        assert_eq!(message, c["message"].as_str().unwrap(), "{name}: message");
        let challenge = webauthn_challenge(PASSKEY_ACCEPTANCE_TAG, message.as_bytes());
        assert_eq!(
            hex::encode(challenge),
            c["challenge"].as_str().unwrap(),
            "{name}"
        );
        let client_data = c["clientDataJSON"].as_str().unwrap().as_bytes();
        assert_eq!(
            check_client_data(client_data, &challenge, request_domain).unwrap(),
            c["origin"].as_str().unwrap()
        );
        let auth = hex::decode(c["authenticatorData"].as_str().unwrap()).unwrap();
        let rp = if request_domain == "localhost" {
            "localhost"
        } else {
            rp_id
        };
        check_authenticator_data(&auth, rp).unwrap();
        let mut signed = auth.clone();
        signed.extend_from_slice(&stele_core::hash::sha256(client_data));
        assert_eq!(
            hex::encode(&signed),
            c["signedBytes"].as_str().unwrap(),
            "{name}"
        );
        let signature: [u8; 64] = hex_n(&c["signature"]);
        let message_hash = stele_core::hash::sha256(message.as_bytes());
        let id = passkey_acceptance_id(
            &hex32(&c["versionAccount"]),
            &signer,
            &message_hash,
            &signature,
        );
        assert_eq!(
            hex::encode(id),
            c["acceptanceId"].as_str().unwrap(),
            "{name}"
        );
    }

    let e = &v["enrollment"];
    let org = b58_32(&e["organization"]);
    let commitment = hex32(&e["accountCommitment"]);
    let statement = enrollment_statement(
        &org,
        &commitment,
        &signer,
        rp_id,
        "Solana Devnet",
        1_790_000_000,
        1_790_000_600,
    )
    .unwrap();
    assert_eq!(statement, e["statement"].as_str().unwrap());
    assert_eq!(
        hex::encode(webauthn_challenge(PASSKEY_ENROLL_TAG, statement.as_bytes())),
        e["challenge"].as_str().unwrap()
    );

    let r = &v["rotation"];
    let next: [u8; 33] = hex_n(&r["newSignerPublicKey"]);
    let statement = rotation_statement(
        &org,
        &commitment,
        &signer,
        &next,
        "Solana Devnet",
        1_790_000_000,
        1_790_000_600,
    )
    .unwrap();
    assert_eq!(statement, r["statement"].as_str().unwrap());
    assert_eq!(
        hex::encode(webauthn_challenge(PASSKEY_ROTATE_TAG, statement.as_bytes())),
        r["challenge"].as_str().unwrap()
    );

    let checks = &v["clientDataChecks"];
    let challenge = hex32(&checks["challenge"]);
    let domain = checks["requestDomain"].as_str().unwrap();
    for c in checks["cases"].as_array().unwrap() {
        let name = c["name"].as_str().unwrap();
        let actual = check_client_data(
            c["clientDataJSON"].as_str().unwrap().as_bytes(),
            &challenge,
            domain,
        );
        match (actual, &c["expected"]) {
            (Ok(origin), expected) => {
                assert_eq!(Some(origin), expected["ok"].as_str(), "{name}")
            }
            (Err(err), expected) => {
                assert_eq!(
                    Some(passkey_error(err)),
                    expected["error"].as_str(),
                    "{name}"
                )
            }
        }
    }

    let checks = &v["authenticatorDataChecks"];
    let rp = checks["rpId"].as_str().unwrap();
    for c in checks["cases"].as_array().unwrap() {
        let name = c["name"].as_str().unwrap();
        let bytes = hex::decode(c["authenticatorData"].as_str().unwrap()).unwrap();
        match (check_authenticator_data(&bytes, rp), &c["expected"]) {
            (Ok(flags), expected) => {
                assert_eq!(Some(u64::from(flags)), expected["ok"].as_u64(), "{name}")
            }
            (Err(err), expected) => {
                assert_eq!(
                    Some(passkey_error(err)),
                    expected["error"].as_str(),
                    "{name}"
                )
            }
        }
    }
}
